'use strict';
(()=>{
 const model=window.CP_MODEL;if(!model)return;
 const el=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function downloadText(text,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 const coverage=el('model-coverage');if(coverage)coverage.innerHTML=model.parties.map((p,i)=>{const count=model.questions.filter(q=>q.positions[i]!==null).length;return `<a class="coverage-row" href="/partidos/${p.slug}/"><img class="party-logo" src="${p.logo}" alt="Logo de ${p.name}" width="56" height="44"><strong>${p.name}</strong><span>${count}/62 · ${Math.round(count/62*100)}% cobertura</span></a>`;}).join('');
 const differences=el('model-differences');if(differences)differences.innerHTML=model.questions.map(q=>{const v=q.positions.filter(x=>x!==null);return {...q,range:Math.max(...v)-Math.min(...v)};}).sort((a,b)=>b.range-a.range||a.id-b.id).slice(0,12).map(q=>`<div class="difference-row"><a href="/temas/${model.topics[q.topic].slug}/">${q.id+1}. ${q.text}</a><span>Rango ${q.range}/4</span></div>`).join('');
 const channel=el('contact-channel');if(channel){const mail=window.CP_CONFIG?.contactEmail;channel.innerHTML=mail?`<p>Correo del proyecto: <a href="mailto:${esc(mail)}">${esc(mail)}</a>.</p>`:'<div class="editorial-note">El correo público del proyecto está pendiente de configuración. Puedes preparar y descargar una propuesta; el formulario no enviará nada sin un canal de contacto disponible.</div>';}
 el('contact-draft')?.addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.target),subject=String(form.get('subject')),message=String(form.get('message'));const text=subject+'\n\n'+message,mail=window.CP_CONFIG?.contactEmail;if(mail){window.location.href='mailto:'+encodeURIComponent(mail)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(message);el('contact-status').textContent='Se ha preparado el borrador para tu aplicación de correo. Debes revisarlo y enviarlo allí.';}else{downloadText(text,'conexion-politica-propuesta.txt');el('contact-status').textContent='Borrador descargado. No se ha enviado ni guardado en el servidor.';}});
 const support=el('support-channel');if(support&&window.CP_CONFIG?.supportURL){const a=document.createElement('a');a.className='button dark-button';a.href=window.CP_CONFIG.supportURL;a.rel='noopener noreferrer';a.target='_blank';a.textContent='Abrir el canal de apoyo';support.append(a);}
 const newsletter=el('newsletter-channel');if(newsletter&&window.CP_CONFIG?.newsletterURL){const a=document.createElement('a');a.className='button light-button';a.href=window.CP_CONFIG.newsletterURL;a.rel='noopener noreferrer';a.target='_blank';a.textContent='Suscribirse por correo en el proveedor externo';newsletter.append(a);}
 el('share-project')?.addEventListener('click',async()=>{const text='Explora tus ideas con Conexión Política: tests de 52 o 62 preguntas, comparación por temas y brújula política. https://conexion-politica.onrender.com/';try{if(navigator.share)await navigator.share({title:'Conexión Política',text});else{await navigator.clipboard.writeText(text);el('share-status').textContent='Enlace copiado. Puedes compartirlo donde quieras.';}}catch(e){if(e.name!=='AbortError')el('share-status').textContent='Comparte este enlace: https://conexion-politica.onrender.com/';}});
 const calculator=el('seat-calculator');if(calculator){
  calculator.innerHTML=`<form id="seat-form" class="panel-form"><div class="compare-selects"><label>Escaños a repartir<input id="seat-count" type="number" min="1" max="100" value="7" required></label><label>Votos en blanco<input id="blank-count" type="number" min="0" max="100000000" value="0" required></label></div><label>Candidaturas y votos, una por línea<textarea id="vote-input" rows="5" required>Lista A, 40000\nLista B, 30000\nLista C, 20000\nLista D, 10000</textarea></label><p>Formato: nombre, votos. Entre 2 y 20 candidaturas. Se aplica el umbral del 3 % de votos válidos.</p><button class="button dark-button" type="submit">Calcular reparto</button><p id="seat-status" role="status"></p></form><div id="seat-result" aria-live="polite"></div>`;
  const compute=e=>{e?.preventDefault();const status=el('seat-status'),result=el('seat-result');status.textContent='';result.innerHTML='';const seats=Number(el('seat-count').value),blank=Number(el('blank-count').value),lines=el('vote-input').value.trim().split('\n');
   try{if(!Number.isInteger(seats)||seats<1||seats>100||!Number.isInteger(blank)||blank<0||blank>100000000)throw Error('Revisa el número de escaños y votos en blanco.');if(lines.length<2||lines.length>20)throw Error('Introduce entre 2 y 20 candidaturas.');const rows=lines.map((line,id)=>{const pos=line.lastIndexOf(','),name=line.slice(0,pos).trim(),raw=line.slice(pos+1).trim();if(pos<1||!name||name.length>80||!/^\d+$/.test(raw)||Number(raw)>100000000)throw Error('Cada línea debe tener un nombre y un número entero de votos, separados por coma.');return {id,name,votes:Number(raw),seats:0};});if(new Set(rows.map(r=>r.name.toLowerCase())).size!==rows.length)throw Error('Utiliza nombres distintos para las candidaturas.');const valid=rows.reduce((s,r)=>s+r.votes,blank);if(!valid)throw Error('Introduce al menos un voto válido.');const eligible=rows.filter(r=>r.votes>0&&r.votes/valid>=.03);if(!eligible.length)throw Error('Ninguna candidatura supera el umbral del 3 %.');const quotients=eligible.flatMap(r=>Array.from({length:seats},(_,i)=>({id:r.id,votes:r.votes,divisor:i+1,value:r.votes/(i+1)}))).sort((a,b)=>b.value-a.value||b.votes-a.votes||a.id-b.id);let lottery=false;for(let i=0;i<seats;i++){const q=quotients[i];rows[q.id].seats++;}const boundary=quotients[seats-1],next=quotients[seats];if(next&&Math.abs(boundary.value-next.value)<1e-9&&boundary.votes===next.votes)lottery=true;
    result.innerHTML=`<h3>Reparto de ${seats} escaños</h3>${lottery?'<div class="editorial-note">Hay un empate en el último escaño que la ley resolvería mediante sorteo. Este ejemplo muestra una asignación provisional por orden de entrada; no es un resultado definitivo.</div>':''}<div class="seat-results">${rows.map(r=>`<div><strong>${esc(r.name)}</strong><span>${r.votes.toLocaleString('es-ES')} votos${r.votes/valid<.03?' · Bajo el umbral':''}</span><b>${r.seats} escaños</b></div>`).join('')}</div><p>${valid.toLocaleString('es-ES')} votos válidos · Umbral: ${(valid*.03).toLocaleString('es-ES')} votos.</p><details><summary>Ver cocientes que reciben escaño</summary><ol>${quotients.slice(0,seats).map(q=>`<li>${esc(rows[q.id].name)}: ${q.votes.toLocaleString('es-ES')} ÷ ${q.divisor} = ${q.value.toLocaleString('es-ES',{maximumFractionDigits:2})}</li>`).join('')}</ol></details>`;
   }catch(error){status.textContent=error.message;}
  };el('seat-form').onsubmit=compute;compute();
 }
 // Search works locally and never transmits a query.
 const directory=document.querySelector('.reading-page .party-directory'),faq=document.querySelector('.reading-page .faq-section');
 if(directory){const search=document.createElement('label');search.className='search-label';search.textContent='Buscar un partido';const input=document.createElement('input');input.type='search';input.placeholder='Nombre o territorio';search.append(input);directory.before(search);const status=document.createElement('p');status.setAttribute('role','status');directory.after(status);input.oninput=()=>{const query=input.value.toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'');let count=0;directory.querySelectorAll('.directory-card').forEach(card=>{card.hidden=!card.textContent.toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(query);if(!card.hidden)count++;});status.textContent=count?'': 'No hay partidos que coincidan con esa búsqueda.';};}
 const menu=document.querySelector('.nav-menu');if(menu){document.addEventListener('click',e=>{if(!menu.contains(e.target))menu.open=false;});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.open){menu.open=false;menu.querySelector('summary').focus();}});}
 // Progressive reveals preserve all content for reduced motion and no-JS visitors.
 if('IntersectionObserver' in window&&!window.matchMedia('(prefers-reduced-motion:reduce)').matches){const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}},{threshold:.07});document.querySelectorAll('.home-screen > .seo-section').forEach(section=>{section.classList.add('reveal');observer.observe(section);});}
})();
